@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {}

class BusinessUser {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + title : string
}

class Track {
  + trackNumber : int
}

class Suggestion {
  + similarityScore : float
}

User --|> RegularUser
User --|> BusinessUser

Artist "1" -- "*" Song
BusinessUser "1" -- "*" Single
BusinessUser "1" -- "*" Hit

RegularUser "1" -- "*" Single : Buy
RegularUser "1" -- "*" Album : Compose

Album "1" *-- "*" Track
Track "1" -- "1" Hit

Hit "1" -- "1" Single : IsSingleOf

RegularUser "1" -- "*" Suggestion
RegularUser "1" -- "*" Suggestion : Receives

@enduml

